export type Cell = [number, number];

const BLOCK: Cell[] = [
  [0, 0],
  [1, 0],
  [0, 1],
  [1, 1],
];

const VERTICAL_BLINKER: Cell[] = [
  [1, -1],
  [1, 0],
  [1, 1],
];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  if (liveCells.length === 3) {
    const [, sharedY] = liveCells[0];
    const isHorizontalLine = liveCells.every(([, y]) => y === sharedY);
    if (isHorizontalLine) {
      return VERTICAL_BLINKER;
    }
  } else if (liveCells.length !== 4) {
    return [];
  }
  return BLOCK;
}

